1	"use server";
2	
3	/**
4	 * Updates one notification preference row.
5	 *
6	 * Owner D. `digestOnly` is only meaningful while the `digest_email` flag is on
7	 * for the organization; asking for it otherwise would strand the notification
8	 * in a digest that never gets sent, so the flag is checked here.
9	 *
10	 * Must call (do not reimplement): updateNotificationPreferenceSchema,
11	 * isEnabled, getActor, toActionResult
12	 */
13	
14	import { FeatureUnavailableError } from "@/actions/_lib/action-errors";
15	import { withAction } from "@/actions/_lib/with-action";
16	import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
17	import { isEnabled } from "@/lib/feature-flags";
18	import {
19	  updateNotificationPreferenceSchema,
20	  type UpdateNotificationPreferenceInput,
21	} from "@/schemas/notification";
22	import { buildFlagContext } from "@/server/services/feature-flag-service";
23	import { updatePreference } from "@/server/services/notification-service";
24	import { getOrganizationSummary } from "@/server/services/organization-service";
25	import type { ActionResult } from "@/types/api";
26	import type { NotificationPreference } from "@/types/notification";
27	
28	const run = withAction<
29	  typeof updateNotificationPreferenceSchema,
30	  NotificationPreference
31	>(
32	  updateNotificationPreferenceSchema,
33	  async (raw, actor) => {
34	    const input = raw as UpdateNotificationPreferenceInput;
35	
36	    const { organization } = await getOrganizationSummary(actor, input.orgId);
37	    const context = buildFlagContext(actor, organization);
