/**
 * The in-app path for an issue, resolved from ids rather than slugs — event
 * payloads only ever carry ids. Returns `null` if the issue, its project or
 * its organization has since disappeared, so a stale event can't produce a
 * notification linking nowhere.
 */
export async function issueHref(
  orgId: OrgId,
  issueId: IssueId,
): Promise<string | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return null;

  const [org, project] = await Promise.all([
    orgRepo.findOrgById(orgId),
    projectRepo.findProjectById(orgId, issue.projectId),
  ]);
  if (!org || !project) return null;

  return issuePath(org.slug, project.slug, issue.number);
}

