  subscribe("issue.assigned", async (payload) => {
    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;

    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href,
      actorId: null,
    });
  });

  // A status change is an `issue:update`, not an assignment, so only the
  // assignee is told — and never about their own move.
  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || issue.assigneeId === null) return;

    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "Issue status changed",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href,
      actorId: payload.actorId,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // Owners run the workspace's membership and billing, so they are the ones
  // told when someone joins — not the person joining, who already knows.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const ownerIds = await memberRepo.listMemberIdsByRole(payload.orgId, "owner");

    await notify(payload.orgId, "member_joined", ownerIds, {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: payload.actorId,
    });
  });

  // One alert per breached resource, addressed to every owner regardless of
  // who tried the write. While it sits unread, further refusals for that
  // same resource are absorbed; once read, the next refusal starts a fresh
  // one. The periodic usage recount never refuses anything, so it never
  // reaches this handler.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = await orgRepo.findOrgById(payload.orgId);
    if (!org) return;

    const ownerIds = await memberRepo.listMemberIdsByRole(payload.orgId, "owner");
    if (ownerIds.length === 0) return;

    const title = `Plan limit reached: ${payload.resource}`;
    const recipients: UserId[] = [];
    for (const ownerId of ownerIds) {
      const existing = await notificationRepo.findUnreadByTitle(
        payload.orgId,
        ownerId,
        title,
      );
      if (existing === null) recipients.push(ownerId);
    }

    await notify(payload.orgId, "plan_limit_reached", recipients, {
      title,
      body: `${payload.resource} is at ${payload.used} of ${payload.limit} on the ${org.plan} plan`,
      href: settingsPath(org.slug, "billing"),
      actorId: null,
    });
  });
}

