/**
 * Resolves a hit to the page the app actually serves: an issue or comment
 * hit links to that issue in its workspace and project, a project hit links
 * to the project. Returns `null` for a stale index row whose subject (or its
 * parent issue/project) has since disappeared.
 */
async function hrefFor(
  orgId: OrgId,
  org: Organization | null,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string | null> {
  if (!org) return null;

  switch (kind) {
    case "issue":
      return issueHref(orgId, subjectId as IssueId);
    case "comment": {
      const comment = await commentRepo.findCommentById(
        orgId,
        subjectId as Comment["id"],
      );
      return comment ? issueHref(orgId, comment.issueId) : null;
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        orgId,
        subjectId as Project["id"],
      );
      return project ? projectPath(org.slug, project.slug) : null;
    }
  }
}

